def parse_csv(raw_csv: str):
    def read_records(text):
        records = []
        row = []
        field = []
        quote = None
        at_field_start = True
        i = 0
        n = len(text)

        while i < n:
            ch = text[i]

            if quote is not None:
                if ch == quote:
                    if i + 1 < n and text[i + 1] == quote:
                        field.append(quote)
                        i += 2
                        continue

                    j = i + 1
                    while j < n and text[j] in " \t":
                        j += 1

                    if j >= n or text[j] == "," or text[j] in "\r\n":
                        quote = None
                        i += 1
                        continue

                    field.append(ch)
                    i += 1
                    continue

                if ch == "\r":
                    if i + 1 < n and text[i + 1] == "\n":
                        i += 1
                    field.append("\n")
                else:
                    field.append(ch)
                i += 1
                continue

            if at_field_start and ch in ("'", '"'):
                quote = ch
                at_field_start = False
                i += 1
                continue

            if ch == ",":
                row.append("".join(field))
                field = []
                at_field_start = True
                i += 1
                continue

            if ch in "\r\n":
                row.append("".join(field))
                records.append(row)
                row = []
                field = []
                at_field_start = True
                if ch == "\r" and i + 1 < n and text[i + 1] == "\n":
                    i += 1
                i += 1
                continue

            field.append(ch)
            at_field_start = False
            i += 1

        if field or row or (n > 0 and text[-1] == ","):
            row.append("".join(field))
            records.append(row)

        return records

    def is_blank(record):
        return not record or all(value.strip() == "" for value in record)

    records = read_records(raw_csv)
    if not records:
        return {"columns": [], "rows": []}

    width_counts = {}
    for record in records:
        if is_blank(record) or len(record) < 2:
            continue
        width_counts[len(record)] = width_counts.get(len(record), 0) + 1

    if width_counts:
        modal_width = max(
            width_counts,
            key=lambda width: (width_counts[width], width)
        )
    else:
        modal_width = max((len(record) for record in records), default=0)

    header_index = None
    for index, record in enumerate(records):
        if not is_blank(record) and len(record) == modal_width:
            header_index = index
            break

    if header_index is None:
        for index, record in enumerate(records):
            if not is_blank(record):
                header_index = index
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    columns = [value.strip() for value in columns]
    width = len(columns)

    rows = []
    for record in records[header_index + 1:]:
        if is_blank(record):
            continue

        current = list(record)

        if len(current) < width:
            current.extend([""] * (width - len(current)))
        elif len(current) > width:
            if width == 0:
                continue
            current = current[:width - 1] + [",".join(current[width - 1:])]

        rows.append([str(value) for value in current])

    return {"columns": columns, "rows": rows}
